7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums per main item type (plus 5 G fee, first insurance 10 %) ---
16	  it("single plain sword, new customer → base premium 100 G", () => {
17	    const result = runScenario({
18	      customer: { yearsWithMHPCO: 0 },
19	      steps: [
20	        {
21	          op: "quote",
22	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
23	        },
24	      ],
25	    });
26	
27	    expect(result).toEqual({ results: [{ premium: 115 }] });
28	  });
