91	
92	    expect(result).toEqual({ results: [{ premium: 60 }] });
93	  });
94	  it("3 runes → 60 G base premium (block of 3 alike applies)", () => {
95	    const result = runScenario({
96	      customer: { yearsWithMHPCO: 0 },
