108	    const result = runScenario({
109	      customer: { yearsWithMHPCO: 0 },
110	      steps: [
111	        {
112	          op: "quote",
113	          items: [
114	            { type: "rune" },
115	            { type: "rune" },
116	            { type: "rune" },
117	            { type: "rune" },
118	          ],
119	        },
