125	  it("7 runes → 175 G base premium (no block for 7)", () => {
126	    const result = runScenario({
127	      customer: { yearsWithMHPCO: 0 },
128	      steps: [
129	        {
130	          op: "quote",
131	          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
