153	  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
154	    const result = runScenario({
155	      customer: { yearsWithMHPCO: 0 },
156	      steps: [
157	        {
158	          op: "quote",
159	          items: [
160	            { type: "rune" },
161	            { type: "rune" },
162	            { type: "rune" },
163	            { type: "moonstone" },
