171	    expect(result).toEqual({ results: [{ premium: 137 }] });
172	  });
173	
174	  // --- Individual premium modifiers ---
175	  it("cursed sword adds a 50 % risk surcharge on the item's base premium", () => {
176	    const result = runScenario({
177	      customer: { yearsWithMHPCO: 0 },
178	      steps: [
