// miss is an error rather than a zero. `quantity` names what is being looked
// up, so the rejection can say which table failed to cover the item.
const lookUpByItemType = (
  table: Record<string, number>,
  item: Item,
  quantity: string,
): number => {
  const value = table[item.type];

  if (value === undefined) {
    throw new Error(`unknown item type "${item.type}": no ${quantity}`);
  }

  return value;
};

